const ic=(n,s=20,c='currentColor',w=1.8)=>`<svg width="${s}" height="${s}" viewBox="0 0 24 24" fill="none" stroke="${c}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${I[n]}</svg>`;
const qr=(s=120,fg='#0F2442',bg='#fff')=>`<svg width="${s}" height="${s}" viewBox="-2 -2 ${QR.n+4} ${QR.n+4}" shape-rendering="crispEdges" role="img" aria-label="Code QR"><rect x="-2" y="-2" width="${QR.n+4}" height="${QR.n+4}" fill="${bg}"/><path d="${QR.d}" fill="${fg}"/></svg>`;
const T=(t)=>`<span class="todo">${t}</span>`;
const NAV=[['home','Accueil'],['about','Qui sommes-nous'],['sol','Nos solutions'],['sect','Secteurs'],['news','Actualités'],['contact','Contact']];
const hd=(a)=>`<header class="hd"><div class="wrap"><a href="#"><img class="logo" src="img/logo.png" alt="DATA TRACE SERVICE"></a><nav class="nav" aria-label="Navigation principale">${NAV.map(n=>`<a class="${n[0]==a?'on':''}">${n[1]}</a>`).join('')}</nav><span class="tel">${ic('phone',18)} +228 XX XX XX XX</span><a class="btn p s">Diagnostic gratuit</a><button class="burger" aria-label="Ouvrir le menu">${ic('menu',22)}</button></div></header>`;
const wa=()=>`<a class="wa" aria-label="Écrire sur WhatsApp">${ic('wa',28)}<span>WhatsApp</span></a><div class="mbar"><a class="btn p">Diagnostic gratuit</a><a class="btn w" aria-label="WhatsApp">${ic('wa',26)}</a></div>`;
const ft=()=>`<footer class="ft"><div class="wrap"><div class="g"><div><img src="img/logo-white.png" alt="DATA TRACE SERVICE" style="height:54px;width:auto"><p style="margin-top:18px;max-width:320px">Traçabilité · Organisation · Qualité. Nous accompagnons les entreprises togolaises dans l’organisation et la digitalisation.</p><div class="soc">${['fb','ig','li','tk'].map(k=>`<i>${ic(k,18)}</i>`).join('')}</div></div>
<div><h5>Le site</h5><ul><li>Accueil</li><li>Qui sommes-nous</li><li>Nos solutions</li><li>Secteurs</li><li>Actualités</li><li>Contact</li></ul></div>
<div><h5>Nos solutions</h5><ul><li>Diagnostic gratuit</li><li>Digitalisation</li><li>Traçabilité</li><li>FeedBack DTS</li><li>Fiabilité des données</li><li>DTS AGRO</li></ul></div>
<div><h5>Nous joindre</h5><ul><li style="display:flex;gap:10px">${ic('pin',18)}Bè Kpota, Lomé, Togo</li><li style="display:flex;gap:10px">${ic('phone',18)}${T('numéro à compléter')}</li><li style="display:flex;gap:10px">${ic('mail',18)}datatraceservice@gmail.com</li></ul></div></div>
<div class="bot"><span>© 2026 DATA TRACE SERVICE SARL U · RCCM ${T('à compléter')} · NIF ${T('à compléter')}</span><span>Mentions légales · Confidentialité · FR</span></div></div></footer>`;
const pg=(a,body,o={})=>(o.nohd?'':hd(a))+body+(o.nofoot?'':ft())+wa();
const stars=(n=5)=>`<span class="stars">${Array.from({length:n},()=>ic('star',14,'currentColor',0)).join('').replace(/fill="none"/g,'fill="currentColor"')}</span>`;
const cta2=()=>`<section class="s"><div class="wrap"><div class="band"><i class="ring"></i><i class="ring2"></i><div style="position:relative"><h2>Prêt à y voir plus clair dans votre entreprise ?</h2><p>Demandez votre diagnostic gratuit dès aujourd’hui. Réponse sous ${T('48 h, à préciser')}.</p></div><div class="card" style="padding:24px;position:relative"><div class="fm"><div><label>Nom et prénoms</label><div class="in ph">Ex. : Akouvi Mensah</div></div><div class="two"><div><label>Téléphone / WhatsApp</label><div class="in ph">+228 …</div></div><div><label>Secteur d’activité</label><div class="in ph">Choisir ${ic('arrow',16).replace('M5 12h14M13 6l6 6-6 6','M6 9l6 6 6-6')}</div></div></div><a class="btn p l" style="width:100%">Demander mon diagnostic gratuit</a><div class="mut" style="font-size:12.5px;text-align:center">Sans engagement. Vos données ne servent qu’à vous répondre.</div></div></div></div></div></section>`;
const photo=(f,pos='50% 30%',h='100%',extra='')=>`<div class="pic" style="height:${h}"><img src="img/${f}.jpg" alt="" style="object-position:${pos}" loading="lazy">${extra}</div>`;
/* mini visuals */
const miniDash=()=>`<div class="mv"><div class="mrow"><span>${stars(5)}</span><b>4,3 / 5</b><span class="sp"></span><span class="tag g">NPS +42</span></div><div class="mrow"><span class="tag r">${ic('alert',13)} Avis négatif</span><span class="sp"></span><span>Table 4 · il y a 6 min</span></div><div class="mrow"><span>Satisfaction</span><span class="sp"></span><b>86 %</b></div></div>`;
