const miniLedger=()=>`<div data-keep style="display:grid;grid-template-columns:minmax(0,1.05fr) 18px minmax(0,1fr);gap:6px;align-items:center"><div class="mv" style="background:repeating-linear-gradient(180deg,#fff 0 22px,#DCE4EE 22px 23px);height:118px;color:var(--muted);font-size:12px;padding:6px 10px;line-height:23px;white-space:nowrap;overflow:hidden">Vendu : 12 sacs<br>Stock ? à vérifier<br>Caisse : …<br>Total ?</div><span style="color:var(--teal-d)">${ic('arrow',18)}</span><div class="mv" style="height:118px;padding:10px"><div class="kpi" style="gap:6px"><div style="padding:6px 8px"><small>Ventes</small><b style="font-size:12.5px;white-space:nowrap">184 500 F</b></div><div style="padding:6px 8px"><small>Stock</small><b style="font-size:12.5px;white-space:nowrap">42 réf.</b></div></div><div class="alrt a" style="font-size:11px;padding:6px 8px">${ic('alert',12)}<span>Stock bas : sucre</span></div></div></div>`;
