const parcel=(w=300,h=160)=>`<svg viewBox="0 0 300 160" ${w=='f'?'style="width:100%;height:auto;display:block"':`width="${w}" height="${h}"`} role="img" aria-label="Parcelles et points GPS"><rect width="300" height="160" rx="12" fill="#E8F1EE"/><path d="M20 120 60 40 130 58 120 130z" fill="#BFE5D6" stroke="#0A7C75" stroke-width="2"/><path d="M118 56 200 36 230 96 150 120z" fill="#BFE5D6" stroke="#0A7C75" stroke-width="2"/><path d="M180 70 250 60 275 120 210 138z" fill="#F6CFC9" stroke="#B42318" stroke-width="2" stroke-dasharray="5 4"/><g fill="#0F2442"><circle cx="60" cy="40" r="4"/><circle cx="130" cy="58" r="4"/><circle cx="200" cy="36" r="4"/><circle cx="230" cy="96" r="4"/></g><circle cx="250" cy="60" r="6" fill="#B42318"/><text x="196" y="150" font-size="11" font-family="Poppins" fill="#B42318" font-weight="600">Chevauchement</text></svg>`;
/* ================= ACCUEIL ================= */
const heroH=()=>`<section class="hero" data-shot><div class="wrap"><div><h1>Gérez votre entreprise <em>à distance</em>, simplement.</h1><p class="lead">Nous commençons par un diagnostic gratuit, puis nous vous proposons une solution de digitalisation simple, adaptée à votre activité.</p><div class="cta"><a class="btn p l">Demander mon diagnostic gratuit</a><a class="btn o l">Découvrir nos solutions</a></div><div class="assure"><span>${ic('check',18)} Gratuit et sans engagement</span><span>${ic('check',18)} Prix annoncés avant de commencer</span><span>${ic('check',18)} Équipe locale à Lomé</span></div></div>
<div class="stage"><div class="ph"><img src="img/couple.jpg" alt="" style="object-position:50% 20%"><span class="demo">Photo de démonstration</span></div>
<div class="fone"><div class="fin"><div class="st"><span>Aujourd’hui</span><span class="tag n" style="padding:2px 8px;font-size:11px">Exemple</span></div><h5>Votre tableau de bord</h5><div class="kpi"><div><small>Ventes</small><b>184 500 F</b></div><div><small>Encaissé</small><b>152 000 F</b></div><div><small>Stock</small><b>42 réf.</b></div><div><small>Avis</small><b>4,3 / 5</b></div></div><div class="alrt a">${ic('alert',14)}<span>Stock bas : sucre (8 kg)</span></div><div class="alrt r">${ic('alert',14)}<span>Avis négatif reçu : table 4</span></div></div></div>
<div class="chip"><i>${ic('bell',18)}</i><span>Un problème survient ? Vous êtes prévenu sur votre téléphone.</span></div></div></div></section>`;
const probS=()=>`<section class="s dk" data-shot><div class="wrap prob"><div><h2 class="h2">Vous devez être sur place pour savoir ce qui se passe ?</h2><p class="sub">Beaucoup de dirigeants gèrent encore leur entreprise avec des cahiers, des fichiers dispersés et leur mémoire. Les conséquences sont les mêmes partout.</p></div><ul>${['Pas de vue d’ensemble sur la production, les stocks, les ventes et l’argent.','Des erreurs et des pertes découvertes trop tard.','Des clients mal connus, dont les avis ne sont jamais recueillis.','Des décisions prises sans chiffres fiables.','Un dirigeant qui ne peut pas s’absenter sans perdre le contrôle.'].map(t=>`<li>${ic('x',22,'currentColor',2)}<span>${t}</span></li>`).join('')}</ul></div></section>`;
const methS=()=>`<section class="s alt" data-shot><div class="wrap"><div class="sec-h"><div><h2 class="h2">Notre méthode en trois étapes</h2><p class="sub">Du diagnostic au pilotage à distance, sans logiciel compliqué.</p></div></div>
<div class="meth"><i class="tr"></i>
<div class="step free"><div class="dot">1</div><h3>Diagnostic gratuit</h3><p>Nous venons comprendre votre entreprise, sans que cela vous coûte quoi que ce soit.</p><ul><li>${ic('check',16)}Échange avec le responsable</li><li>${ic('check',16)}Observation des ventes, stocks, clients et flux</li><li>${ic('check',16)}Court compte rendu des priorités</li></ul><div style="margin-top:16px"><span class="tag">Sans engagement</span></div></div>
<div class="step"><div class="dot">2</div><h3>Une solution simple</h3><p>La solution la plus simple qui résout vos vrais problèmes, au prix annoncé avant de commencer.</p><ul><li>${ic('check',16)}Proposition claire : quoi, quand, combien</li><li>${ic('check',16)}Démarrage petit, puis extension</li><li>${ic('check',16)}Installation et formation de vos équipes</li></ul></div>
<div class="step"><div class="dot">3</div><h3>Gestion à distance</h3><p>Vous pilotez votre entreprise où que vous soyez, depuis votre téléphone ou votre ordinateur.</p><ul><li>${ic('check',16)}Tableau de bord et alertes</li><li>${ic('check',16)}Rapports prêts à lire</li><li>${ic('check',16)}Suivi et support après la mise en place</li></ul></div></div></div></section>`;
const solS=()=>`<section class="s" data-shot><div class="wrap"><div class="sec-h"><div><h2 class="h2">Des solutions concrètes, choisies selon votre besoin</h2></div><a class="lnk">Toutes nos solutions ${ic('arrow',18)}</a></div>
<div class="bento"><div class="bc navy b7"><span class="tag" style="align-self:flex-start">Notre produit phare</span><h3>FeedBack DTS</h3><p>Vos clients scannent un code QR et répondent en moins d’une minute. Vous voyez la note, la satisfaction et les alertes sur votre téléphone.</p>${miniDash()}<a class="lnk">Découvrir FeedBack DTS ${ic('arrow',18)}</a></div>
<div class="bc b5"><h3>Traçabilité</h3><p>De la réception des matières premières à la vente, retrouvez l’historique d’un produit avec un code QR.</p>${miniLot()}<a class="lnk">Voir la traçabilité ${ic('arrow',18)}</a></div>
<div class="bc b4"><h3>Digitalisation des processus</h3><p>Ventes, stocks, achats, production et caisse au même endroit.</p>${miniLedger()}<a class="lnk">En savoir plus ${ic('arrow',18)}</a></div>
<div class="bc b4"><h3>Fiabilité des données</h3><p>Doublons, fiches incomplètes, coordonnées erronées : nous les repérons et vous remettons des fichiers propres.</p>${miniData()}<a class="lnk">En savoir plus ${ic('arrow',18)}</a></div>
<div class="bc b4"><h3>DTS AGRO</h3><p>Producteurs, collecte, parcelles, intrants : une plateforme modulaire pour les coopératives.</p>${parcel('f')}<a class="lnk">Voir les modules ${ic('arrow',18)}</a></div>
<div class="bc b8"><h3>Applications web et mobiles sur mesure</h3><p>Un besoin précis ? Nous concevons l’application web, mobile ou la solution en abonnement (SaaS) qui lui correspond.</p><div class="chips" style="margin-top:6px"><span>Application web</span><span>Application mobile</span><span>Solution SaaS</span></div><a class="lnk">Parler de mon projet ${ic('arrow',18)}</a></div>
<div class="bc tint b4"><h3>Pas sûr de ce qu’il vous faut ?</h3><p style="color:var(--ink)">Commencez par le diagnostic gratuit. Nous vous disons ce qui peut être amélioré.</p><a class="btn n" style="margin-top:auto">Diagnostic gratuit</a></div></div></div></section>`;
const whyS=()=>`<section class="s alt" data-shot><div class="wrap"><div class="sec-h"><div><h2 class="h2">Pourquoi choisir DATA TRACE SERVICE</h2></div></div><div class="why">${[['target','Diagnostic gratuit','Vous ne prenez aucun risque pour commencer.'],['hand','Solutions simples','Vous n’avez pas besoin d’être informaticien.'],['phoneS','Gestion à distance','Vous gardez le contrôle même quand vous n’êtes pas sur place.'],['layers','Vue globale','Production, ventes, stocks, flux financiers et clients au même endroit.'],['wallet','Pensé pour le terrain','Des outils qui fonctionnent avec une connexion faible et des équipes peu à l’aise avec l’informatique.'],['users','Accompagnement','Installation, formation et suivi, pas seulement un logiciel.'],['trend','Évolutif','On commence par un besoin, on ajoute le reste plus tard.'],['shield','Données fiables et tracées','Vous décidez avec des chiffres exacts.']].map(r=>`<div>${ic(r[0],28)}<div style="display:block;padding:0;border:0"><h4>${r[1]}</h4><p>${r[2]}</p></div></div>`).join('')}</div></div></section>`;
const secS=()=>`<section class="s" data-shot><div class="wrap"><div class="sec-h"><div><h2 class="h2">Des secteurs où la traçabilité change tout</h2></div><a class="lnk">Tous les secteurs ${ic('arrow',18)}</a></div><div class="mos">
<a class="tile t5 wide"><img src="img/chef.jpg" alt="" style="object-position:50% 40%"><div><h4>Restauration et commerce</h4><p>Ventes, stocks, avis par QR code, flux du jour</p></div></a>
<a class="tile t4"><img src="img/tech.jpg" alt="" style="object-position:50% 20%"><div><h4>Production et agroalimentaire</h4><p>Lots, matières premières, pertes</p></div></a>
<a class="tile t3 map" style="padding:0"><div style="width:100%;padding:0;display:flex;flex-direction:column;justify-content:space-between"><div style="padding:16px 18px 0">${parcel('f')}</div><div style="padding:0 20px 18px"><h4>Agriculture</h4><p>Producteurs, collecte, parcelles</p></div></div></a>
<a class="tile t4"><img src="img/spray.jpg" alt="" style="object-position:50% 30%"><div><h4>Santé</h4><p>Avis anonymes des patients, qualité de l’accueil</p></div></a>
<a class="tile t4"><img src="img/pw-form.jpg" alt="" style="object-position:50% 35%"><div><h4>Éducation</h4><p>Avis des étudiants et des parents</p></div></a>
<a class="tile t4"><img src="img/speaker.jpg" alt="" style="object-position:50% 20%"><div><h4>Événements</h4><p>Avis des participants, rapport final</p></div></a></div></div></section>`;
const R={};
R.home=()=>pg('home',heroH()+probS(),{nofoot:1});
R.home2=()=>pg('home',methS(),{nofoot:1,nohd:1});
R.home3=()=>pg('home',solS(),{nofoot:1,nohd:1});
R.home4=()=>pg('home',whyS()+secS(),{nofoot:1,nohd:1});
R.home5=()=>pg('home',cta2(),{nohd:1});
/* ================= QUI SOMMES-NOUS ================= */
R.about=()=>pg('about',`<section class="ph2" data-shot><div class="wrap"><div><div class="crumb"><span>Accueil</span>/<b>Qui sommes-nous</b></div><h1>Le numérique doit être simple, utile et accessible à tous les chefs d’entreprise.</h1><p class="lead">DATA TRACE SERVICE est une entreprise togolaise spécialisée dans la traçabilité, l’organisation et la digitalisation. Notre mission : accompagner les entreprises pour mieux maîtriser leur activité et améliorer leurs performances.</p></div>${photo('openspace','50% 40%','400px','<span class="demo">Photo de démonstration</span>')}</div></section>
<section class="s"><div class="wrap"><div class="sec-h"><h2 class="h2">Nos valeurs</h2></div><div class="rows">${[['Simplicité','Des solutions faciles à prendre en main, même sans être informaticien.'],['Transparence','Un diagnostic gratuit, des propositions claires, des prix annoncés avant de commencer.'],['Fiabilité','Des données justes et tracées, sur lesquelles on peut décider.'],['Proximité','Une équipe locale, qui comprend les réalités des entreprises togolaises et reste disponible après la mise en place.'],['Progression','On commence petit, on ajoute des fonctions au rythme de l’entreprise.']].map(r=>`<div><h3>${r[0]}</h3><p>${r[1]}</p></div>`).join('')}</div></div></section>
<section class="s alt"><div class="wrap" style="display:grid;grid-template-columns:minmax(0,.8fr) minmax(0,1.2fr);gap:56px;align-items:start"><div class="imgph" style="aspect-ratio:4/5">Photo de la Gérante<br>à fournir</div><div><h2 class="h2">TINDJO N’tchièbini</h2><p class="mut" style="margin-top:6px;font-weight:500">Gérante de DATA TRACE SERVICE</p><p class="sub">${T('Texte de présentation de la Gérante à fournir')}</p><div class="card" style="margin-top:28px;padding:6px 22px"><table><tr><td class="mut" style="width:180px">Forme juridique</td><td><b>SARL U</b>, selon les lois en vigueur au Togo</td></tr><tr><td class="mut">Siège</td><td><b>Bè Kpota, Lomé, Togo</b></td></tr><tr><td class="mut">E-mail</td><td><b>datatraceservice@gmail.com</b></td></tr><tr><td class="mut">Slogan</td><td><b>Traçabilité · Organisation · Qualité</b></td></tr></table></div></div></div></section>`+cta2());
/* ================= DIAGNOSTIC ================= */
const formDiag=(err)=>`<div class="card" style="padding:32px;box-shadow:var(--sh)"><h3 style="font-size:24px">Demandez votre diagnostic gratuit</h3><p class="mut" style="margin:6px 0 22px;font-size:15px">Moins d’une minute. Nous vous répondons sous ${T('48 h, à préciser')}.</p><div class="fm">
<div><label for="n">Nom et prénoms</label><div class="in ${err?'er':'f'}" id="n">${err?'':'Akouvi M'}</div>${err?`<div class="err">${ic('alert',15)}Indiquez votre nom et prénoms.</div>`:''}</div>
<div><label>Entreprise</label><div class="in ph">Nom de votre entreprise</div></div>
<div class="two"><div><label>Téléphone / WhatsApp</label><div class="in ${err?'er':'ph'}">${err?'+228 9':'+228 …'}</div>${err?`<div class="err">${ic('alert',15)}Numéro trop court.</div>`:''}</div><div><label>E-mail <small>(facultatif)</small></label><div class="in ph">vous@exemple.com</div></div></div>
<div class="two"><div><label>Secteur d’activité</label><div class="in ph">Choisir ${ic('arrow',16).replace('M5 12h14M13 6l6 6-6 6','M6 9l6 6 6-6')}</div></div><div><label>Ville</label><div class="in ph">Lomé</div></div></div>
<div><label>Votre principal souci aujourd’hui <small>(facultatif)</small></label><div class="in ph ta">Ex. : je ne sais pas ce qu’il me reste en stock…</div></div>
<div class="ck"><i class="${err?'':'on'}">${err?'':ic('check',14,'#fff',3)}</i><span>J’accepte d’être contacté par DATA TRACE SERVICE au sujet de ma demande.</span></div>
<a class="btn p l" style="width:100%">Demander mon diagnostic gratuit</a><a class="btn w" style="width:100%">${ic('wa',22)} Préférer WhatsApp</a></div></div>`;
R.diag=(err)=>pg('diag',`<section class="ph2" style="padding-bottom:72px" data-shot><div class="wrap" style="grid-template-columns:minmax(0,1fr) minmax(0,1fr);align-items:start"><div><div class="crumb"><span>Accueil</span>/<b>Diagnostic gratuit</b></div><h1>Avant de vous proposer quoi que ce soit, nous venons comprendre votre entreprise.</h1><p class="lead">Notre diagnostic est gratuit et sans engagement. Nous identifions ce qui vous fait perdre du temps ou de l’argent, et nous vous disons ce qui peut être amélioré par le numérique.</p><ul style="list-style:none;margin:32px 0 0;padding:0;display:grid;gap:16px">${['Échange avec le responsable pour comprendre son activité et ses difficultés.','Observation de la façon dont vous gérez ventes, stocks, production, clients et flux financiers.','Identification des pertes de temps, des risques d’erreur et des informations qui vous manquent.','Remise d’un court compte rendu avec les points à améliorer en priorité.','Sans engagement : vous restez libre de donner suite ou non.'].map(t=>`<li style="display:flex;gap:14px;align-items:flex-start"><span style="flex:none;width:26px;height:26px;border-radius:50%;background:var(--teal-s);color:var(--teal-d);display:grid;place-items:center;margin-top:2px">${ic('check',15,'currentColor',2.6)}</span>${t}</li>`).join('')}</ul><p class="mut" style="margin-top:26px;font-size:14.5px">Durée et conditions du diagnostic : ${T('à préciser par la Gérante')}</p></div>${formDiag(err)}</div></section>`);
R.diage=()=>R.diag(true);
R.merci=()=>pg('diag',`<section class="s" style="padding:80px 0 100px"><div class="wrap" style="max-width:760px"><div class="card" style="padding:48px;text-align:center;box-shadow:var(--sh)"><span style="width:72px;height:72px;border-radius:50%;background:var(--teal);color:var(--navy-d);display:inline-grid;place-items:center">${ic('check',36,'currentColor',2.6)}</span><h1 style="font-size:36px;margin-top:24px">Merci, votre demande est bien reçue</h1><p class="sub" style="margin:14px auto 0">Nous vous répondons sous ${T('48 h, à préciser')}. Un e-mail de confirmation vient de vous être envoyé.</p><div class="card" style="margin:32px 0;padding:6px 22px;text-align:left;background:var(--canvas)"><table><tr><td class="mut" style="width:150px">Nom</td><td><b>Akouvi Mensah</b></td></tr><tr><td class="mut">Entreprise</td><td><b>Boulangerie La Spirale</b></td></tr><tr><td class="mut">Secteur</td><td><b>Restauration et commerce · Lomé</b></td></tr></table></div><div style="display:flex;gap:14px;justify-content:center;flex-wrap:wrap"><a class="btn w">${ic('wa',22)} Écrire sur WhatsApp</a><a class="btn o">Retour à l’accueil</a></div></div></div></section>`);
/* ================= SOLUTIONS ================= */
const sHero=(crumb,h1,lead,vis,btns=1)=>`<section class="ph2" data-shot><div class="wrap"><div><div class="crumb"><span>Accueil</span>/<span>Nos solutions</span>/<b>${crumb}</b></div><h1>${h1}</h1><p class="lead">${lead}</p>${btns?`<div style="display:flex;gap:12px;flex-wrap:wrap;margin-top:30px"><a class="btn p l">Demander mon diagnostic gratuit</a></div>`:''}</div><div>${vis}</div></div></section>`;
const ben=(l)=>`<section class="s"><div class="wrap"><div class="rows">${l.map(r=>`<div><h3>${r[0]}</h3><div>${r[1]}</div></div>`).join('')}</div></div></section>`;
const ul=(a)=>`<ul>${a.map(t=>`<li>${ic('check',16)}${t}</li>`).join('')}</ul>`;
R.sol=()=>pg('sol',`<section class="ph2" data-shot style="padding-bottom:48px"><div class="wrap" style="grid-template-columns:minmax(0,1fr)"><div><div class="crumb"><span>Accueil</span>/<b>Nos solutions</b></div><h1 style="max-width:860px">Des solutions simples pour piloter votre entreprise.</h1><p class="lead">Chaque solution peut démarrer seule, puis s’ajouter aux autres au rythme de votre activité.</p></div></div></section>
<section class="s" style="padding-top:24px"><div class="wrap"><div class="rows">${[['Diagnostic gratuit','Pour tout responsable qui veut y voir plus clair. Nous analysons votre fonctionnement et vous disons ce qui peut être amélioré par le numérique.','Vous gagnez une vision claire de vos priorités, sans risque.'],['Digitalisation des processus','Des outils simples qui remplacent les cahiers et réunissent ventes, stocks, achats, production et caisse au même endroit.','Gain de temps, moins d’erreurs, informations disponibles à distance.'],['Traçabilité','Suivi de chaque lot, de la réception des matières premières à la vente, avec l’historique d’un produit par code QR.','Qualité maîtrisée, pertes réduites, confiance des clients.'],['FeedBack DTS','Vos clients scannent un code QR et répondent en moins d’une minute. Note moyenne, satisfaction, NPS et alertes sur votre tableau de bord.','Connaître ses clients, réagir vite, améliorer son service avec des faits.'],['Fiabilité des données','Contrôle automatique de vos fichiers, rapport Excel des anomalies avec priorités et corrections proposées, puis fichiers propres.','Des données fiables pour les rapports, les paiements et les audits.'],['DTS AGRO','Plateforme modulaire pour coopératives, exportateurs et transformateurs : AgroID, Collecte, ParcelCheck, Intrants, AgroFactory, HarvestPredict.','On commence par un module et on ajoute les autres selon le besoin.'],['Applications sur mesure','Applications web, mobiles et solutions en abonnement (SaaS) pour répondre à un besoin précis de l’entreprise.','Un outil qui correspond à votre façon de travailler.']].map(r=>`<div><div><h3>${r[0]}</h3></div><div><p>${r[1]}</p><p style="margin-top:10px;color:var(--navy-d);font-weight:500">${r[2]}</p><a class="lnk" style="margin-top:14px">Voir la solution ${ic('arrow',18)}</a></div></div>`).join('')}</div></div></section>`+cta2());
R.digi=()=>pg('sol',sHero('Digitalisation des processus','Remplacez les cahiers par un outil qui réunit tout.','Ventes, stocks, achats, production et caisse sont encore gérés sur papier ou dans des fichiers dispersés ? Nous les rassemblons au même endroit, accessibles à distance.',`<div class="card" style="padding:22px;box-shadow:var(--sh)"><div style="display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:16px"><div><div class="tag a" style="margin-bottom:10px">Avant</div><div style="background:repeating-linear-gradient(180deg,#fff 0 27px,#DCE4EE 27px 28px);border:1px solid var(--line);border-radius:10px;padding:12px 14px;height:260px;line-height:28px;font-size:14px;color:var(--muted)">Vendu : 12 sacs<br>Reste en stock ?<br>Acheté chez M. K. : 40 000<br>Caisse : à compter<br><span style="text-decoration:line-through">Total ?</span></div></div><div><div class="tag g" style="margin-bottom:10px">Après</div><div style="border:1px solid var(--line);border-radius:10px;padding:12px;height:260px"><div class="kpi"><div><small>Ventes</small><b>184 500 F</b></div><div><small>Caisse</small><b>152 000 F</b></div><div><small>Achats</small><b>40 000 F</b></div><div><small>Stock</small><b>42 réf.</b></div></div><div class="alrt a" style="margin-top:12px">${ic('alert',14)}<span>Stock bas : sucre (8 kg)</span></div><div class="mut" style="font-size:11px;margin-top:12px">Exemple de démonstration</div></div></div></div></div>`)+ben([['Ce que nous mettons en place',ul(['Suivi des ventes et de la caisse, jour après jour','Gestion des stocks et des achats','Suivi de la production et des pertes','Un tableau de bord sur téléphone ou ordinateur'])],['Comment ça se passe',`<p>Nous démarrons petit, par exemple le suivi des ventes et des stocks, puis la solution s’agrandit. Installation, configuration et formation de vos équipes sont comprises dans la proposition.</p>`],['Ce que vous gagnez',ul(['Du temps : plus de recopie ni de calculs à la main','Moins d’erreurs et de pertes','L’information disponible même quand vous n’êtes pas sur place'])]])+cta2());
R.trac=()=>pg('sol',sHero('Traçabilité','Sachez d’où vient chaque produit, et où il est allé.','Suivi de chaque lot, de la réception des matières premières à la vente, avec l’historique d’un produit grâce à un code QR.',`<div style="display:grid;grid-template-columns:minmax(0,1fr) 200px;gap:20px;align-items:end"><div class="card" style="padding:22px;box-shadow:var(--sh)"><b style="font-size:14px">Lot L-2026-118 · Jus de bissap 33 cl</b><div class="tl" style="margin-top:18px">${[['Réception hibiscus · 3 nov.','Fournisseur identifié, 120 kg'],['Fabrication · 4 nov.','Chef de production, cuve 2'],['Mise en stock · 5 nov.','Entrepôt Bè, 480 bouteilles'],['Vente · 7 nov.','Client : boutique Adidogomé']].map((r,i)=>`<div><i class="${i>2?'g':''}"></i><div><b style="font-size:14px">${r[0]}</b><div class="mut" style="font-size:13px">${r[1]}</div></div></div>`).join('')}</div></div><div class="card" style="padding:14px;text-align:center;box-shadow:var(--sh)">${qr(170)}<div style="font-size:12px;margin-top:6px;font-weight:600">Scannez pour voir l’historique</div></div></div>`)+`<section class="s alt"><div class="wrap"><div class="sec-h"><h2 class="h2">Le parcours d’un lot</h2></div><div class="lot">${[['box','Réception','Matières premières contrôlées'],['factory','Fabrication','Lot créé, recette suivie'],['layers','Stock','Quantités et dates'],['cart','Vente','Client et paiement']].map((r,i)=>`<div><span class="nd">${ic(r[0],22,'#fff')}</span>${i<3?'<i class="ln"></i>':''}<div><b>${r[1]}</b><small>${r[2]}</small></div></div>`).join('')}</div></div></section>`+ben([['Ce que vous gagnez',ul(['Qualité maîtrisée : vous retrouvez l’origine d’un problème en quelques secondes','Pertes réduites, écarts repérés tôt','Confiance des clients : l’historique est consultable par QR code','Vue globale sur les flux et les flux financiers'])]])+cta2());
R.fb=()=>pg('sol',sHero('FeedBack DTS','Vos clients vous disent ce qu’ils pensent. Vous le savez tout de suite.','Le client scanne un code QR, répond à quelques questions en moins d’une minute, et vous voyez les résultats sur votre tableau de bord.',`<div class="dash"><div class="bar"><i></i><i></i><i></i><span>feedback.datatraceservice · Exemple de démonstration</span></div><div class="bd"><div class="k4"><div><small>Note moyenne</small><b>4,3</b> <em class="up">+0,2</em></div><div><small>Satisfaction</small><b>86 %</b></div><div><small>NPS</small><b>+42</b></div><div><small>Avis négatifs</small><b>3</b> <em class="dn">à traiter</em></div></div><div class="alrt r" style="margin-top:14px;font-size:13px">${ic('alert',16)}<span><b>Avis négatif</b> · Table 4 · « Attente trop longue » · il y a 6 min</span></div><div class="bchart" style="margin-top:16px">${[40,52,48,66,60,74,70,88,82,95,90,100].map((v,i)=>`<i class="${i>9?'t':''}" style="height:${v}%"></i>`).join('')}</div></div></div>`)+`<section class="s alt"><div class="wrap"><div class="sec-h"><h2 class="h2">Comment ça marche</h2></div><div style="display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr) minmax(0,1fr);gap:28px;align-items:start"><div><div class="card" style="padding:20px;display:inline-block;background:var(--canvas)">${qr(150)}</div><h3 style="font-size:21px;margin:18px 0 8px">1. Le client scanne</h3><p class="mut">Le code QR est posé sur la table, au comptoir ou à l’accueil.</p></div><div><div style="width:150px;background:var(--navy-d);border-radius:22px;padding:6px"><div style="background:#fff;border-radius:17px;padding:14px 12px;height:180px"><b style="font-size:11px">Votre avis en 1 minute</b><div class="rate" style="margin-top:12px;gap:4px">${[1,2,3,4,5].map(n=>`<i style="border-radius:8px;font-size:12px;${n==4?'background:var(--navy);color:#fff':''}">${n}</i>`).join('')}</div><div class="in" style="min-height:44px;font-size:11px;margin-top:12px">Un commentaire ?</div></div></div><h3 style="font-size:21px;margin:18px 0 8px">2. Il répond</h3><p class="mut">Quelques questions, moins d’une minute, sans créer de compte.</p></div><div><div class="card" style="padding:16px">${miniDash()}</div><h3 style="font-size:21px;margin:18px 0 8px">3. Vous agissez</h3><p class="mut">Note moyenne, satisfaction, NPS et alerte immédiate sur un avis négatif.</p></div></div></div></section>`+`<section class="s"><div class="wrap"><div class="sec-h"><h2 class="h2">Pour qui ?</h2></div><div class="chips" style="gap:12px">${['Restaurants','Commerces','Centres de santé','Écoles et universités','Événements'].map(t=>`<span style="padding:12px 20px;font-size:16px">${t}</span>`).join('')}</div><p class="sub" style="margin-top:28px">Connaître ses clients, réagir vite, améliorer son service avec des faits.</p><div style="margin-top:28px"><a class="btn n l">Demander une démonstration</a></div></div></section>`+cta2());
R.fiab=()=>pg('sol',sHero('Fiabilité des données','Des bases de producteurs ou de clients enfin propres.','Doublons, fiches incomplètes, coordonnées erronées : nous contrôlons vos fichiers, vous remettons un rapport Excel des anomalies, puis des fichiers prêts à réutiliser.',`<div class="dash"><div class="bar"><i></i><i></i><i></i><span>Rapport d’anomalies · Exemple de démonstration</span></div><div class="bd" style="padding:0"><table><tr><th>Anomalie</th><th>Fiche</th><th>Priorité</th><th>Correction proposée</th></tr>${[['Doublon','P-0412 / P-0987','r','Fusionner les deux fiches'],['Téléphone manquant','P-0233','a','Compléter auprès de la coopérative'],['Coordonnées GPS','Parcelle 118','a','Revérifier sur le terrain'],['Nom en double','P-0650','g','Corriger l’orthographe']].map(r=>`<tr><td><b>${r[0]}</b></td><td class="mut">${r[1]}</td><td><span class="tag ${r[2]}">${{r:'Haute',a:'Moyenne',g:'Basse'}[r[2]]}</span></td><td>${r[3]}</td></tr>`).join('')}</table><div style="padding:14px 16px;border-top:1px solid var(--line);display:flex;justify-content:space-between;align-items:center"><span class="mut" style="font-size:13px">248 fiches contrôlées · 4 anomalies</span><a class="btn n s">${ic('xls',16)} Télécharger le rapport Excel</a></div></div></div>`)+`<section class="s alt"><div class="wrap"><div class="sec-h"><h2 class="h2">Trois temps, un résultat</h2></div><div class="lot" style="grid-template-columns:repeat(3,1fr)">${[['search','Contrôle automatique','Vos fichiers sont analysés en une fois'],['xls','Rapport d’anomalies','Priorités et corrections proposées'],['db','Fichiers propres','Prêts pour votre outil actuel']].map((r,i)=>`<div><span class="nd">${ic(r[0],22,'#fff')}</span>${i<2?'<i class="ln"></i>':''}<div><b>${r[1]}</b><small>${r[2]}</small></div></div>`).join('')}</div></div></section>`+ben([['Pour qui',`<p>Coopératives, exportateurs, programmes et entreprises dont les bases de producteurs ou de clients contiennent des doublons, des fiches incomplètes ou des coordonnées erronées.</p>`],['Ce que vous gagnez',ul(['Données fiables pour les rapports, les paiements et les audits','Un rapport Excel facile à partager','Des fichiers propres, sans changer d’outil'])]])+cta2());
R.agro=()=>pg('sol',sHero('DTS AGRO','Traçabilité et gestion agricole, module après module.','Une plateforme modulaire pour les coopératives, exportateurs et transformateurs. Chaque client commence avec un module et ajoute les autres selon ses besoins.',`<div class="card" style="padding:18px;box-shadow:var(--sh)">${parcel('f')}<div style="display:flex;gap:10px;margin-top:12px;align-items:center"><span class="tag r">${ic('alert',13)} 1 chevauchement</span><span class="mut" style="font-size:13px">ParcelCheck · exemple de démonstration</span></div></div>`)+`<section class="s alt"><div class="wrap"><div class="sec-h"><div><h2 class="h2">Six modules, à la carte</h2><p class="sub">Offre en cours de déploiement : ${T('modules disponibles à confirmer par la Gérante')}</p></div></div><div class="rows">${[['AgroID','Identifie chaque producteur de façon unique : carte avec QR code, parcelles, historique, détection des doublons.','QR'],['Collecte','Enregistre chaque livraison et rapproche automatiquement achats, stocks et paiements.',''],['ParcelCheck','Contrôle les parcelles : coordonnées GPS suspectes, parcelles qui se chevauchent.',''],['Intrants','Suit la distribution des semences et engrais aux producteurs.',''],['AgroFactory','Digitalise les unités de transformation et retrace chaque lot jusqu’au produit fini.',''],['HarvestPredict','Aide à prévoir les récoltes et à planifier les approvisionnements.','']].map(r=>`<div><div><h3>${r[0]}</h3><span class="tag a" style="margin-top:8px">À confirmer</span></div><div style="display:flex;gap:24px;justify-content:space-between"><p>${r[1]}</p>${r[2]?`<div class="card" style="padding:8px;flex:none">${qr(84)}</div>`:''}</div></div>`).join('')}</div></div></section>`+cta2());
R.surm=()=>pg('sol',sHero('Applications sur mesure','Un besoin précis ? Nous construisons l’outil qui lui correspond.','Conception d’applications web, mobiles et de solutions en abonnement (SaaS) pour répondre à un besoin précis de votre entreprise.',`<div style="display:grid;grid-template-columns:minmax(0,1fr) 150px;gap:16px;align-items:end"><div class="dash"><div class="bar"><i></i><i></i><i></i><span>Application web</span></div><div class="bd"><div class="k4" style="grid-template-columns:minmax(0,1fr) minmax(0,1fr)"><div><small>Commandes</small><b>128</b></div><div><small>Livrées</small><b>112</b></div></div><div class="bchart" style="margin-top:14px;height:90px">${[30,45,40,62,58,80,76].map(v=>`<i style="height:${v}%"></i>`).join('')}</div></div></div><div style="width:150px;background:var(--navy-d);border-radius:22px;padding:6px"><div style="background:#fff;border-radius:17px;padding:12px;height:230px"><b style="font-size:11px">Application mobile</b><div class="mv" style="margin-top:10px;font-size:11px">Commande n° 128<br><span class="tag g" style="font-size:11px">Livrée</span></div></div></div></div>`)+ben([['Ce que nous construisons',ul(['Application web et site de gestion','Application mobile (Android et iPhone)','Solution en abonnement (SaaS) pour vos clients'])],['Comment nous travaillons',`<div class="lot" style="grid-template-columns:repeat(4,1fr)">${[['Besoin','Échange et cadrage'],['Maquettes','Validation avant de coder'],['Développement','Livraisons régulières'],['Mise en ligne','Formation et suivi']].map((r,i)=>`<div><span class="nd">${i+1}</span>${i<3?'<i class="ln"></i>':''}<div><b>${r[0]}</b><small>${r[1]}</small></div></div>`).join('')}</div>`]])+cta2());
